?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Approvals | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=439" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=505"></script></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">Dance Cup Approvals</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="participants.php">Participants</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></div></nav><main class="container py-4" style="max-width:1150px"><h1 class="h3">Pending Dance Cup Result Approval</h1><p class="text-muted">Submission freezes the complete result for review. Open the dedicated review screen before accepting any result. Projection reveal is controlled separately.</p><?php foreach($rows as $row):?><section class="card border-warning shadow-sm mb-3"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><span class="badge text-bg-warning">PENDING SUPER ADMIN APPROVAL</span><h2 class="h5 mt-2 mb-1"><?=e($row['category_name'])?></h2><p class="text-muted mb-1"><?=e($row['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$row['dance_style'])))?> · <?=e(ucwords(str_replace('_',' ',$row['entry_type'])))?> · <?=e(ucwords(str_replace('_',' ',$row['competition_level'])))?></p><small><?=e(ucfirst($row['scoring_mode']))?> · <?=$row['contestants']?> contestants · <?=$row['results']?> calculated results · <?=(int)$row['private_comments']?> private comments · submitted <?=e((string)$row['submitted_at'])?></small></div><div class="d-flex gap-2 flex-wrap"><a class="btn btn-outline-secondary" href="<?=$row['scoring_mode']==='automatic'?'automatic-setup.php':'category.php'?>?id=<?=(int)$row['id']?>">Open Scoring Workspace</a><a class="btn btn-primary" href="approval-review.php?id=<?=(int)$row['id']?>">Review Result, Comments &amp; Accept</a></div></div></div></section><?php endforeach;?><?php if(!$rows):?><div class="card border-0 shadow-sm"><div class="card-body text-center text-muted py-5">No Dance Cup results are waiting for approval.</div></div><?php endif;?></main></body></html>
